}

solution_code:
fn parse_positive(s: &str) -> Result<i32, String> {
    match s.parse::<i32>() {
        Ok(n) if n > 0 => Ok(n),
        Ok(_) => Err(format!("{} 不是正整数", s)),
        Err(_) => Err(format!("无法解析: {}", s)),
    }
}

