## 路径处理
```rust
use std::path::Path;
use std::path::PathBuf;

let path = Path::new("/usr/local/bin");
path.parent();       // Some(/usr/local)
path.file_name();    // Some(bin)
path.extension();    // None

let mut buf = PathBuf::from("/usr");
buf.push("local");    // /usr/local
buf.set_extension("txt");  // /usr/local.txt
```

## 目录操作
```rust
