solution_code:
fn build_query(table: &str, conditions: &Vec<(&str, &str)>) -> String {
    if conditions.is_empty() {
        format!("SELECT * FROM {}", table)
    } else {
        let where_clause: Vec<String> = conditions
            .iter()
            .map(|(k, v)| format!("{}='{}'", k, v))
            .collect();
        format!("SELECT * FROM {} WHERE {}", table, where_clause.join(" AND "))
    }
}

